struct Concept { virtual ~Concept() = default; virtual void draw(std::ostream&) = 0;
                 virtual std::unique_ptr<Concept> clone() const = 0; };  // erased interface
template <class T> struct Model final : Concept {
  T v; explicit Model(T x) : v(std::move(x)) {}
  void draw(std::ostream& o) override { v.draw(o); }
  std::unique_ptr<Concept> clone() const override {
    return std::unique_ptr<Concept>(new Model(*this)); } };

class Drawable { std::unique_ptr<Concept> self_;                       // value handle
public:
  template <class T> Drawable(T x) : self_(new Model<T>(std::move(x))) {}  // bind: T known
  void draw(std::ostream& o) { self_->draw(o); }                           // dispatch: T erased
};

